        // Validate maxWalletAmount is now zero
        uint256 updatedMaxWallet = token.maxWalletAmount();
        assertEq(updatedMaxWallet, 0, "maxWallet should be zero");

        // Transfer should revert (both user and recipient are non-excluded)
        vm.prank(user);
        vm.expectRevert();
        token.transfer(recipient, initialUserBalance);
